void BehaviorPathPlannerNode::run()
{
  const auto stamp = this->now();

  takeData();

  const auto data_ready_status = isDataReady(stamp);
  // `DataReadyStatus::TIMEOUT` is not handled intentionally as the reason in "NOTE" below
  if (data_ready_status == DataReadyStatus::NOT_RECEIVED) {
    /*
     * NOTE:
     * To preserve the existing logic of the run() callback,
     * the run() callback will return early when mandatory data not received.
     * There is controversy about the behavior when data is timed out. It will be discussed in the
     * future.
     */
    diagnostics_message_timeout_->publish(stamp);
    return;
  }

  RCLCPP_DEBUG(get_logger(), "----- BehaviorPathPlannerNode start -----");

  // behavior_path_planner runs only in LANE DRIVING scenario.
  if (current_scenario_->current_scenario != Scenario::LANEDRIVING) {
    diagnostics_message_timeout_->publish(stamp);
    return;
  }

  // check for map update
  LaneletMapBin::ConstSharedPtr map_ptr{nullptr};
  {
    if (has_received_map_) {
      // Note: duplicating the shared_ptr prevents the data from being deleted by another thread!
      map_ptr = map_ptr_;
      has_received_map_ = false;
    }
  }

  // check for route update
  LaneletRoute::ConstSharedPtr route_ptr{nullptr};
  {
    if (has_received_route_) {
      // Note: duplicating the shared_ptr prevents the data from being deleted by another thread!
      route_ptr = route_ptr_;
      has_received_route_ = false;
    }
  }

  std::unique_lock<std::mutex> lk_pd(mutex_pd_);  // for planner_data_

  // update map
  if (map_ptr) {
    planner_data_->route_handler->setMap(*map_ptr);
  }

  std::unique_lock<std::mutex> lk_manager(mutex_manager_);  // for planner_manager_

  // update route
  const bool is_first_time = !(planner_data_->route_handler->isHandlerReady());
  if (route_ptr) {
    planner_data_->route_handler->setRoute(*route_ptr);
    // uuid is not changed when rerouting with modified goal,
    // in this case do not need to reset modules.
    const bool has_same_route_id =
      planner_data_->prev_route_id && route_ptr->uuid == planner_data_->prev_route_id;
    // Reset behavior tree when new route is received,
    // so that the each modules do not have to care about the "route jump".
    if (!is_first_time && !has_same_route_id) {
      RCLCPP_INFO(get_logger(), "New uuid route is received. Resetting modules.");
      planner_manager_->reset();
      planner_manager_->resetCurrentRouteLanelet(planner_data_);
      planner_data_->prev_modified_goal.reset();
    }
  }
  const auto controlled_by_autoware_autonomously =
    planner_data_->operation_mode->mode == OperationModeState::AUTONOMOUS &&
    planner_data_->operation_mode->is_autoware_control_enabled;
  if (
    !controlled_by_autoware_autonomously &&
    !planner_manager_->hasPossibleRerouteApprovedModules(planner_data_))
    planner_manager_->resetCurrentRouteLanelet(planner_data_);

  // run behavior planner
  const auto output = planner_manager_->run(planner_data_);

  // path handling
  const auto path = getPath(output, planner_data_);
  path->header.stamp = stamp;
  // update planner data
  planner_data_->prev_output_path = path;

  // compute turn signal
  computeTurnSignal(planner_data_, *path, output);

  // publish reroute availability
  publish_reroute_availability();

  // publish drivable bounds
  publish_bounds(*path);

  // NOTE: In order to keep backward_path_length at least, resampling interval is added to the
  // backward.
  const auto current_pose = planner_data_->self_odometry->pose.pose;
  if (!path->points.empty()) {
    const size_t current_seg_idx = planner_data_->findEgoSegmentIndex(path->points);
    path->points = autoware::motion_utils::cropPoints(
      path->points, current_pose.position, current_seg_idx,
      planner_data_->parameters.forward_path_length,
      planner_data_->parameters.backward_path_length +
        planner_data_->parameters.input_path_interval);

    if (!path->points.empty()) {
      path_publisher_->publish(*path);
      published_time_publisher_->publish_if_subscribed(path_publisher_, path->header.stamp);
    } else {
      RCLCPP_ERROR_THROTTLE(
        get_logger(), *get_clock(), 5000, "behavior path output is empty! Stop publish.");
    }
  } else {
    RCLCPP_ERROR_THROTTLE(
      get_logger(), *get_clock(), 5000, "behavior path output is empty! Stop publish.");
  }

  publishSceneModuleDebugMsg(planner_manager_->getDebugMsg());
  publishPathCandidate(planner_manager_->getSceneModuleManagers(), planner_data_);
  publishPathReference(planner_manager_->getSceneModuleManagers(), planner_data_);

  // publish modified goal only when it is updated
  if (
    output.modified_goal &&
    /* has changed modified goal */ (
      !planner_data_->prev_modified_goal || autoware_utils::calc_distance2d(
                                              planner_data_->prev_modified_goal->pose.position,
                                              output.modified_goal->pose.position) > 0.01)) {
    PoseWithUuidStamped modified_goal = *(output.modified_goal);
    modified_goal.header.stamp = path->header.stamp;
    planner_data_->prev_modified_goal = modified_goal;
    modified_goal_publisher_->publish(modified_goal);
  }

  planner_data_->prev_route_id = planner_data_->route_handler->getRouteUuid();

  lk_pd.unlock();  // release planner_data_

  planner_manager_->print();
  planner_manager_->publishProcessingTime();
  planner_manager_->publishMarker();
  planner_manager_->publishVirtualWall();
  lk_manager.unlock();  // release planner_manager_

  // publish diagnostics for timeout checking.
  diagnostics_message_timeout_->publish(stamp);

  RCLCPP_DEBUG(get_logger(), "----- behavior path planner end -----\n\n");
}

void BehaviorPathPlannerNode::takeData()
{
  // route
  {
    const auto msg = route_subscriber_.take_data();
    if (msg) {
      if (msg->segments.empty()) {
        RCLCPP_ERROR(get_logger(), "input route is empty. ignored");
      } else {
        route_ptr_ = msg;
        has_received_route_ = true;
      }
    }
  }
  // map
  {
    const auto msg = vector_map_subscriber_.take_data();
    if (msg) {
      map_ptr_ = msg;
      has_received_map_ = true;
    }
  }
  // velocity
  {
    const auto msg = velocity_subscriber_.take_data();
    if (msg) {
      planner_data_->self_odometry = msg;
    }
  }
  // acceleration
  {
    const auto msg = acceleration_subscriber_.take_data();
    if (msg) {
      planner_data_->self_acceleration = msg;
    }
  }
  // scenario
  {
    const auto msg = scenario_subscriber_.take_data();
    if (msg) {
      current_scenario_ = msg;
    }
  }
  // perception
  {
    const auto msg = perception_subscriber_.take_data();
    if (msg) {
      planner_data_->dynamic_object = msg;
    }
  }
  // occupancy_grid
  {
    const auto msg = occupancy_grid_subscriber_.take_data();
    if (msg) {
      planner_data_->occupancy_grid = msg;
    }
  }
  // costmap
  {
    const auto msg = costmap_subscriber_.take_data();
    if (msg) {
      planner_data_->costmap = msg;
    }
  }
  // traffic_signal
  {
    const auto msg = traffic_signals_subscriber_.take_data();
    if (msg) {
      onTrafficSignals(msg);
    }
  }
  // lateral_offset
  {
    const auto msg = lateral_offset_subscriber_.take_data();
    if (msg) {
      onLateralOffset(msg);
    }
  }
  // operation_mode
  {
    const auto msg = operation_mode_subscriber_.take_data();
    if (msg) {
      planner_data_->operation_mode = msg;
    }
  }
  // external_velocity_limiter
  {
    const auto msg = external_limit_max_velocity_subscriber_.take_data();
    if (msg) {
      planner_data_->external_limit_max_velocity = msg;
    }
  }
}

typename MessageT::ConstSharedPtr take_data();

/**
 * @brief Getter for timestamp of the last message
 *
 * @pre To receive a valid timestamp, the most recent take_data() call must have successfully
 *      received a message. The timestamp is cleared when no data is returned.
 * @return std::optional<rclcpp::Time> The last timestamp. std::nullopt if no message has been
 * received in the most recent take_data() call.
 */
std::optional<rclcpp::Time> last_taken_data_timestamp() const { return timestamp_; }

BehaviorPathPlannerNode::DataReadyStatus BehaviorPathPlannerNode::isDataReady(
  const rclcpp::Time & now)
{
  diagnostics_message_timeout_->clear();
  DataReadyStatus status = DataReadyStatus::SUCCESS;

  // 1: Check if mandatory data has been received at least once.
  {
    const auto update_reception_diagnostics = [&](const auto & ptr, const std::string & name) {
      if (!ptr) {
        RCLCPP_INFO_SKIPFIRST_THROTTLE(
          get_logger(), *get_clock(), 5000, "waiting for %s", name.c_str());
        diagnostics_message_timeout_->add_key_value(name, std::string("not received"));
        status = DataReadyStatus::NOT_RECEIVED;
        return;
      }
      diagnostics_message_timeout_->add_key_value(name, std::string("OK"));
    };

    update_reception_diagnostics(route_ptr_, "route");
    update_reception_diagnostics(map_ptr_, "vector_map");
    update_reception_diagnostics(current_scenario_, "scenario");
    update_reception_diagnostics(planner_data_->self_acceleration, "acceleration");
    update_reception_diagnostics(planner_data_->operation_mode, "operation_mode");
  }

  // Step 2: Check if cyclic data is not timed out instead of `topic_state_monitor`.
  {
    const auto update_timeout_diagnostics =
      [&](const std::optional<rclcpp::Time> & ts, double timeout, const std::string & name) {
        if (!ts.has_value()) {
          RCLCPP_INFO_SKIPFIRST_THROTTLE(
            get_logger(), *get_clock(), 5000, "waiting for %s", name.c_str());
          diagnostics_message_timeout_->add_key_value(name, std::string("not received"));
          status = DataReadyStatus::NOT_RECEIVED;
          return;
        }
        if ((now - ts.value()).seconds() > timeout) {
          diagnostics_message_timeout_->add_key_value(name, std::string("timeout"));
          if (status == DataReadyStatus::SUCCESS) {
            status = DataReadyStatus::TIMEOUT;
          }
          return;
        }
        diagnostics_message_timeout_->add_key_value(name, std::string("OK"));
      };

    update_timeout_diagnostics(
      perception_subscriber_.last_taken_data_timestamp(), cyclic_message_timeout_,
      "perception_objects");
    update_timeout_diagnostics(
      velocity_subscriber_.last_taken_data_timestamp(), cyclic_message_timeout_, "odometry");
    update_timeout_diagnostics(
      occupancy_grid_subscriber_.last_taken_data_timestamp(), cyclic_message_timeout_,
      "occupancy_grid_map");
    if (enable_traffic_signal_timeout_) {
      update_timeout_diagnostics(
        traffic_signals_subscriber_.last_taken_data_timestamp(), cyclic_message_timeout_,
        "traffic_signal");
    }
  }

  if (status != DataReadyStatus::SUCCESS) {
    diagnostics_message_timeout_->update_level_and_message(
      diagnostic_msgs::msg::DiagnosticStatus::ERROR, "message timeout detected");
  }

  return status;
}

void RouteHandler::setMap(const LaneletMapBin & map_msg)
{
  lanelet_map_ptr_ = autoware::experimental::lanelet2_utils::remove_const(
    autoware::experimental::lanelet2_utils::from_autoware_map_msgs(map_msg));
  auto routing_graph_and_traffic_rules =
    autoware::experimental::lanelet2_utils::instantiate_routing_graph_and_traffic_rules(
      lanelet_map_ptr_);
  routing_graph_ptr_ =
    autoware::experimental::lanelet2_utils::remove_const(routing_graph_and_traffic_rules.first);
  traffic_rules_ptr_ = routing_graph_and_traffic_rules.second;
  const auto map_major_version_opt =
    lanelet::io_handlers::parseMajorVersion(map_msg.version_map_format);
  if (!map_major_version_opt) {
    RCLCPP_WARN(
      logger_, "setMap() for invalid version map: %s", map_msg.version_map_format.c_str());
  } else if (map_major_version_opt.value() > static_cast<uint64_t>(lanelet::autoware::version)) {
    RCLCPP_WARN(
      logger_, "setMap() for a map(version %s) newer than lanelet2_extension support version(%d)",
      map_msg.version_map_format.c_str(), static_cast<int>(lanelet::autoware::version));
  }

  const auto traffic_rules = lanelet::traffic_rules::TrafficRulesFactory::create(
    lanelet::Locations::Germany, lanelet::Participants::Vehicle);
  const auto pedestrian_rules = lanelet::traffic_rules::TrafficRulesFactory::create(
    lanelet::Locations::Germany, lanelet::Participants::Pedestrian);
  const lanelet::routing::RoutingGraphConstPtr vehicle_graph =
    lanelet::routing::RoutingGraph::build(*lanelet_map_ptr_, *traffic_rules);
  const lanelet::routing::RoutingGraphConstPtr pedestrian_graph =
    lanelet::routing::RoutingGraph::build(*lanelet_map_ptr_, *pedestrian_rules);
  const lanelet::routing::RoutingGraphContainer overall_graphs({vehicle_graph, pedestrian_graph});
  overall_graphs_ptr_ =
    std::make_shared<const lanelet::routing::RoutingGraphContainer>(overall_graphs);
  lanelet::ConstLanelets all_lanelets = lanelet::utils::query::laneletLayer(lanelet_map_ptr_);

  is_map_msg_ready_ = true;
  is_handler_ready_ = false;

  setLaneletsFromRouteMsg();
}

lanelet::LaneletMapConstPtr from_autoware_map_msgs(
  const autoware_map_msgs::msg::LaneletMapBin & msg)
{
  std::string data_str;
  data_str.assign(msg.data.begin(), msg.data.end());

  std::stringstream ss;
  ss << data_str;
  boost::archive::binary_iarchive oa(ss);

  auto lanelet_map_ptr = std::make_shared<lanelet::LaneletMap>();
  oa >> *lanelet_map_ptr;
  lanelet::Id id_counter = 0;
  oa >> id_counter;
  lanelet::utils::registerId(id_counter);

  return lanelet_map_ptr;
}

instantiate_routing_graph_and_traffic_rules(
  lanelet::LaneletMapConstPtr lanelet_map, const char * location, const char * participant)
{
  auto traffic_rules = lanelet::traffic_rules::TrafficRulesFactory::create(location, participant);
  return {
    lanelet::routing::RoutingGraph::build(*lanelet_map, *traffic_rules), std::move(traffic_rules)};
}

void RouteHandler::setLaneletsFromRouteMsg()
{
  if (!route_ptr_ || !is_map_msg_ready_) {
    return;
  }
  route_lanelets_.clear();
  route_lanelets_rtree_.clear();
  preferred_lanelets_.clear();
  const bool is_route_valid = lanelet::utils::route::isRouteValid(*route_ptr_, lanelet_map_ptr_);
  if (!is_route_valid) {
    return;
  }

  size_t primitive_size{0};
  for (const auto & route_section : route_ptr_->segments) {
    primitive_size += route_section.primitives.size();
  }
  route_lanelets_.reserve(primitive_size);
  std::vector<RouteRtreeNode> rtree_nodes;
  rtree_nodes.reserve(primitive_size);
  size_t i = 0;

  for (const auto & route_section : route_ptr_->segments) {
    for (const auto & primitive : route_section.primitives) {
      const auto id = primitive.id;
      const auto & llt = lanelet_map_ptr_->laneletLayer.get(id);
      route_lanelets_.push_back(llt);
      rtree_nodes.emplace_back(
        boost::geometry::return_envelope<autoware_utils_geometry::Box2d>(
          llt.polygon2d().basicPolygon()),
        i++);
      if (id == route_section.preferred_primitive.id) {
        preferred_lanelets_.push_back(llt);
      }
    }
  }
  route_lanelets_rtree_ = RouteRtree(rtree_nodes);
  goal_lanelets_.clear();
  start_lanelets_.clear();
  if (!route_ptr_->segments.empty()) {
    goal_lanelets_.reserve(route_ptr_->segments.back().primitives.size());
    for (const auto & primitive : route_ptr_->segments.back().primitives) {
      const auto id = primitive.id;
      const auto & llt = lanelet_map_ptr_->laneletLayer.get(id);
      goal_lanelets_.push_back(llt);
    }
    start_lanelets_.reserve(route_ptr_->segments.front().primitives.size());
    for (const auto & primitive : route_ptr_->segments.front().primitives) {
      const auto id = primitive.id;
      const auto & llt = lanelet_map_ptr_->laneletLayer.get(id);
      start_lanelets_.push_back(llt);
    }
  }
  is_handler_ready_ = true;
}

void RouteHandler::setRoute(const LaneletRoute & route_msg)
{
  if (!isRouteLooped(route_msg.segments)) {
    // if get not modified route but new route, reset original start pose
    if (!route_ptr_ || route_ptr_->uuid != route_msg.uuid) {
      original_start_pose_ = route_msg.start_pose;
      original_goal_pose_ = route_msg.goal_pose;
    }
    route_ptr_ = std::make_shared<LaneletRoute>(route_msg);
    is_handler_ready_ = false;
    setLaneletsFromRouteMsg();
  } else {
    RCLCPP_ERROR(
      logger_,
      "Loop detected within route! Currently, no loop is allowed for route! Using previous route");
  }
}

bool RouteHandler::isRouteLooped(const RouteSections & route_sections)
{
  std::set<lanelet::Id> lane_primitives;
  for (const auto & route_section : route_sections) {
    for (const auto & primitive : route_section.primitives) {
      if (lane_primitives.find(primitive.id) != lane_primitives.end()) {
        return true;  // find duplicated id
      }
      lane_primitives.emplace(primitive.id);
    }
  }
  return false;
}

