lanelet::ConstLineString3d get_closest_segment(
  const lanelet::ConstLineString3d & linestring, const lanelet::BasicPoint3d & search_pt)
{
  lanelet::ConstLineString3d closest_segment;
  double min_distance = std::numeric_limits<double>::max();

  for (const auto & [prev_pt, current_pt] :
       ranges::views::zip(linestring, linestring | ranges::views::drop(1))) {
    lanelet::Point3d prev_pt_3d(lanelet::InvalId, prev_pt.x(), prev_pt.y(), prev_pt.z());
    lanelet::Point3d current_pt_3d(
      lanelet::InvalId, current_pt.x(), current_pt.y(), current_pt.z());

    lanelet::ConstLineString3d current_segment(lanelet::InvalId, {prev_pt_3d, current_pt_3d});
    double distance = lanelet::geometry::distance3d(current_segment.basicLineString(), search_pt);
    if (distance < min_distance) {
      closest_segment = current_segment;
      min_distance = distance;
    }
  }
  return closest_segment;
}

void resetCurrentRouteLanelet(const std::shared_ptr<PlannerData> & data)
{
  lanelet::ConstLanelet ret{};
  data->route_handler->getClosestLaneletWithinRoute(data->self_odometry->pose.pose, &ret);
  RCLCPP_DEBUG(logger_, "update current route lanelet. id:%ld", ret.id());
  *current_route_lanelet_ = ret;
}

bool RouteHandler::getClosestLaneletWithinRoute(
  const Pose & search_pose, lanelet::ConstLanelet * closest_lanelet) const
{
  if (route_lanelets_.empty() || closest_lanelet == nullptr) {
    return false;
  }
  const auto search_point = lanelet::BasicPoint2d(search_pose.position.x, search_pose.position.y);
  const auto query_nearest = boost::geometry::index::nearest(search_point, route_lanelets_.size());
  auto min_dist_to_route_lanelet = std::numeric_limits<double>::max();
  size_t nearest_id = 0;
  // search starting from the nearest bounding box
  for (auto query_it = route_lanelets_rtree_.qbegin(query_nearest);
       query_it != route_lanelets_rtree_.qend(); ++query_it) {
    const auto dist_to_bbox = boost::geometry::comparable_distance(search_point, query_it->first);
    // stop when the distance to the bounding box is larger than the min distance found so far
    if (dist_to_bbox > min_dist_to_route_lanelet) {
      break;
    }
    const auto dist = boost::geometry::comparable_distance(
      search_point, route_lanelets_[query_it->second].polygon2d().basicPolygon());
    if (dist < min_dist_to_route_lanelet) {
      min_dist_to_route_lanelet = dist;
      nearest_id = query_it->second;
    }
  }
  *closest_lanelet = route_lanelets_[nearest_id];
  return true;
}

bool isEgoOutOfRoute(
  const Pose & self_pose, const lanelet::ConstLanelet & closest_road_lane,
  const std::optional<PoseWithUuidStamped> & modified_goal,
  const std::shared_ptr<RouteHandler> & route_handler)
{
  const Pose & goal_pose = (modified_goal && modified_goal->uuid == route_handler->getRouteUuid())
                             ? modified_goal->pose
                             : route_handler->getGoalPose();

  lanelet::ConstLanelet goal_lane;
  const auto shoulder_goal_lanes = route_handler->getShoulderLaneletsAtPose(goal_pose);
  if (!shoulder_goal_lanes.empty()) goal_lane = shoulder_goal_lanes.front();
  const auto is_failed_getting_lanelet =
    shoulder_goal_lanes.empty() && !route_handler->getGoalLanelet(&goal_lane);
  if (is_failed_getting_lanelet) {
    RCLCPP_WARN_STREAM(
      rclcpp::get_logger("behavior_path_planner").get_child("util"), "cannot find goal lanelet");
    return true;
  }

  // If ego vehicle is over goal on goal lane, return true
  const double yaw_threshold = autoware_utils::deg2rad(90);
  if (
    closest_road_lane.id() == goal_lane.id() &&
    isInLaneletWithYawThreshold(self_pose, goal_lane, yaw_threshold)) {
    constexpr double buffer = 1.0;
    const auto ego_arc_coord =
      autoware::experimental::lanelet2_utils::get_arc_coordinates({goal_lane}, self_pose);
    const auto goal_arc_coord = autoware::experimental::lanelet2_utils::get_arc_coordinates(
      {goal_lane}, route_handler->getGoalPose());
    if (ego_arc_coord.length > goal_arc_coord.length + buffer) {
      RCLCPP_WARN_STREAM(
        rclcpp::get_logger("behavior_path_planner").get_child("util"), "ego pose is beyond goal");
      return true;
    }
    return false;
  }

  // If ego vehicle is out of the closest lanelet, return true
  // Check if ego vehicle is in shoulder lane
  const bool is_in_shoulder_lane = !route_handler->getShoulderLaneletsAtPose(self_pose).empty();
  // Check if ego vehicle is in road lane
  const bool is_in_road_lane = std::invoke([&]() {
    if (autoware::experimental::lanelet2_utils::is_in_lanelet(self_pose, closest_road_lane)) {
      return true;
    }

    // check previous lanes for backward driving (e.g. pull out)
    const auto prev_lanes = route_handler->getPreviousLanelets(closest_road_lane);
    for (const auto & lane : prev_lanes) {
      if (autoware::experimental::lanelet2_utils::is_in_lanelet(self_pose, lane)) {
        return true;
      }
    }

    return false;
  });

  return !is_in_shoulder_lane && !is_in_road_lane;
}

UUID RouteHandler::getRouteUuid() const
{
  if (!route_ptr_) {
    RCLCPP_WARN_SKIPFIRST(logger_, "[Route Handler] getRouteUuid: Route has not been set yet");
    return UUID();
  }
  return route_ptr_->uuid;
}

lanelet::ConstLanelets RouteHandler::getShoulderLaneletsAtPose(const Pose & pose) const
{
  lanelet::ConstLanelets lanelets_at_pose;
  const lanelet::BasicPoint2d p{pose.position.x, pose.position.y};
  const auto candidates_at_pose = lanelet_map_ptr_->laneletLayer.search(lanelet::BoundingBox2d(p));
  for (const auto & candidate : candidates_at_pose) {
    // confirm that the pose is inside the lanelet since "search" does an approximation with boxes
    const auto is_pose_inside_lanelet = lanelet::geometry::inside(candidate, p);
    if (is_pose_inside_lanelet && isShoulderLanelet(candidate))
      lanelets_at_pose.push_back(candidate);
  }
  return lanelets_at_pose;
}

bool RouteHandler::isShoulderLanelet(const lanelet::ConstLanelet & lanelet) const
{
  return lanelet.hasAttribute(lanelet::AttributeName::Subtype) &&
         lanelet.attribute(lanelet::AttributeName::Subtype) == "road_shoulder";
}

bool RouteHandler::getGoalLanelet(lanelet::ConstLanelet * goal_lanelet) const
{
  const lanelet::Id goal_lane_id = getGoalLaneId();
  for (const auto & llt : route_lanelets_) {
    if (llt.id() == goal_lane_id) {
      *goal_lanelet = llt;
      return true;
    }
  }
  return false;
}

lanelet::Id RouteHandler::getGoalLaneId() const
{
  if (!route_ptr_ || route_ptr_->segments.empty()) {
    return lanelet::InvalId;
  }

  return route_ptr_->segments.back().preferred_primitive.id;
}

bool isInLaneletWithYawThreshold(
  const Pose & current_pose, const lanelet::ConstLanelet & lanelet, const double yaw_threshold,
  const double radius)
{
  const double pose_yaw = tf2::getYaw(current_pose.orientation);
  const double lanelet_angle = autoware::experimental::lanelet2_utils::get_lanelet_angle(
    lanelet, autoware::experimental::lanelet2_utils::from_ros(current_pose.position).basicPoint());
  const double angle_diff = std::abs(autoware_utils::normalize_radian(lanelet_angle - pose_yaw));

  return (angle_diff < std::abs(yaw_threshold)) &&
         autoware::experimental::lanelet2_utils::is_in_lanelet(current_pose, lanelet, radius);
}

double get_lanelet_angle(
  const lanelet::ConstLanelet & lanelet, const lanelet::BasicPoint3d & search_pt)
{
  lanelet::ConstLineString3d segment = get_closest_segment(lanelet.centerline(), search_pt);
  return std::atan2(
    segment.back().y() - segment.front().y(), segment.back().x() - segment.front().x());
}

lanelet::ConstLineString3d get_closest_segment(
  const lanelet::ConstLineString3d & linestring, const lanelet::BasicPoint3d & search_pt)
{
  lanelet::ConstLineString3d closest_segment;
  double min_distance = std::numeric_limits<double>::max();

  for (const auto & [prev_pt, current_pt] :
       ranges::views::zip(linestring, linestring | ranges::views::drop(1))) {
    lanelet::Point3d prev_pt_3d(lanelet::InvalId, prev_pt.x(), prev_pt.y(), prev_pt.z());
    lanelet::Point3d current_pt_3d(
      lanelet::InvalId, current_pt.x(), current_pt.y(), current_pt.z());

    lanelet::ConstLineString3d current_segment(lanelet::InvalId, {prev_pt_3d, current_pt_3d});
    double distance = lanelet::geometry::distance3d(current_segment.basicLineString(), search_pt);
    if (distance < min_distance) {
      closest_segment = current_segment;
      min_distance = distance;
    }
  }
  return closest_segment;
}

inline double normalize_radian(const double rad, const double min_rad = -pi)
{
  const auto max_rad = min_rad + 2 * pi;

  const auto value = std::fmod(rad, 2 * pi);
  if (min_rad <= value && value < max_rad) {
    return value;
  }

  return value - std::copysign(2 * pi, value);
}

bool is_in_lanelet(
  const geometry_msgs::msg::Pose & pose, const lanelet::ConstLanelet & lanelet, const double radius)
{
  constexpr double epsilon = 1.0e-9;
  const double abs_radius = radius >= 0 ? radius : std::fabs(radius);
  if (radius < 0) {
    RCLCPP_WARN(
      rclcpp::get_logger("autoware_lanelet_utility"),
      "Input radius is negative, applying absolute.");
  }
  const lanelet::BasicPoint2d p(pose.position.x, pose.position.y);
  return boost::geometry::distance(p, lanelet.polygon2d().basicPolygon()) < abs_radius + epsilon;
}

bool is_in_lanelet(
  const geometry_msgs::msg::Pose & pose, const lanelet::ConstLanelet & lanelet, const double radius)
{
  constexpr double epsilon = 1.0e-9;
  const double abs_radius = radius >= 0 ? radius : std::fabs(radius);
  if (radius < 0) {
    RCLCPP_WARN(
      rclcpp::get_logger("autoware_lanelet_utility"),
      "Input radius is negative, applying absolute.");
  }
  const lanelet::BasicPoint2d p(pose.position.x, pose.position.y);
  return boost::geometry::distance(p, lanelet.polygon2d().basicPolygon()) < abs_radius + epsilon;
}

SlotOutput SubPlannerManager::propagateFull(
  const std::shared_ptr<PlannerData> & data, const SlotOutput & previous_slot_output)
{
  const size_t module_size = manager_ptrs_.size();
  const size_t max_iteration_num = static_cast<int>(module_size * (module_size + 1) / 2);

  bool is_waiting_approved_slot = previous_slot_output.is_upstream_waiting_approved;
  bool is_failed_approved_slot = false;
  auto output_path = previous_slot_output.valid_output;

  std::vector<SceneModulePtr> deleted_modules;
  for (size_t itr_num = 0; itr_num < max_iteration_num; ++itr_num) {
    const auto approved_module_result =
      runApprovedModules(data, previous_slot_output.valid_output, deleted_modules);
    const auto & approved_module_output = approved_module_result.valid_output;

    // these status needs to be propagated to downstream slots
    // if any of the slots returned following statuses, keep it
    is_waiting_approved_slot =
      is_waiting_approved_slot || approved_module_result.is_upstream_waiting_approved;
    is_failed_approved_slot =
      is_failed_approved_slot || approved_module_result.is_upstream_failed_approved;

    const auto request_modules = getRequestModules(approved_module_output, deleted_modules);
    if (request_modules.empty()) {
      // there is no module that needs to be launched
      return SlotOutput{
        approved_module_output, isAnyCandidateExclusive(), is_failed_approved_slot,
        is_waiting_approved_slot};
    }

    const auto [highest_priority_module, candidate_module_output] =
      runRequestModules(request_modules, data, approved_module_output);

    if (!highest_priority_module) {
      // there is no need to launch new module
      return SlotOutput{
        approved_module_output, isAnyCandidateExclusive(), is_failed_approved_slot,
        is_waiting_approved_slot};
    }

    if (highest_priority_module->isWaitingApproval()) {
      // there is no need to launch new module
      return SlotOutput{
        candidate_module_output, isAnyCandidateExclusive(), is_failed_approved_slot,
        is_waiting_approved_slot};
    }

    output_path = candidate_module_output;
    addApprovedModule(highest_priority_module);
    clearCandidateModules();
  }

  return SlotOutput{
    output_path, isAnyCandidateExclusive(), is_failed_approved_slot, is_waiting_approved_slot};
}

SlotOutput SubPlannerManager::runApprovedModules(
  const std::shared_ptr<PlannerData> & data, const BehaviorModuleOutput & upstream_slot_output,
  std::vector<SceneModulePtr> & deleted_modules)
{
  std::unordered_map<std::string, BehaviorModuleOutput> results;
  BehaviorModuleOutput output = upstream_slot_output;
  results.emplace("root", output);

  const bool is_candidate_plan_applied = true /* NOTE: not used in this process */;
  bool is_this_failed = false;
  bool is_this_waiting_approval = false;

  if (approved_module_ptrs_.empty()) {
    return SlotOutput{output, is_candidate_plan_applied, is_this_failed, is_this_waiting_approval};
  }

  // unlock only last approved module
  std::for_each(approved_module_ptrs_.begin(), approved_module_ptrs_.end(), [&](const auto & m) {
    m->lockOutputPath();
  });
  approved_module_ptrs_.back()->unlockOutputPath();

  /**
   * bootstrap approved module output
   */
  std::for_each(approved_module_ptrs_.begin(), approved_module_ptrs_.end(), [&](const auto & m) {
    output = run(m, data, output);
    results.emplace(m->name(), output);
  });

  const auto waiting_approval_modules_itr = std::find_if(
    approved_module_ptrs_.begin(), approved_module_ptrs_.end(),
    [](const auto & m) { return m->isWaitingApproval(); });

  if (waiting_approval_modules_itr != approved_module_ptrs_.end()) {
    is_this_waiting_approval = true;

    // only keep this module as candidate
    clearCandidateModules();
    candidate_module_ptrs_.push_back(*waiting_approval_modules_itr);

    // delete following result but keep the rest of the following modules
    std::for_each(
      waiting_approval_modules_itr, approved_module_ptrs_.end(),
      [&results](const auto & m) { results.erase(m->name()); });
    debug_info_.scene_status.emplace_back(
      *waiting_approval_modules_itr, SceneModuleUpdateInfo::Action::MOVE,
      "Back To Waiting Approval");
    approved_module_ptrs_.erase(waiting_approval_modules_itr);

    std::for_each(
      manager_ptrs_.begin(), manager_ptrs_.end(), [](const auto & m) { m->updateObserver(); });
  }

  /**
   * remove failure modules. these modules' outputs are discarded as invalid plan.
   */
  const auto failed_itr = std::find_if(
    approved_module_ptrs_.begin(), approved_module_ptrs_.end(),
    [](const auto & m) { return m->getCurrentStatus() == ModuleStatus::FAILURE; });
  if (failed_itr != approved_module_ptrs_.end()) {
    is_this_failed = true;

    // clear all candidates
    clearCandidateModules();

    // delete both subsequent result and modules
    std::for_each(failed_itr, approved_module_ptrs_.end(), [&](auto & m) {
      results.erase(m->name());
      debug_info_.scene_status.emplace_back(
        m, SceneModuleUpdateInfo::Action::DELETE, "From Approved");
      // NOTE(soblin): m is copied, so it is okay to call deleteExpiredModules
      deleted_modules.push_back(m);
      deleteExpiredModules(m);
    });
    approved_module_ptrs_.erase(failed_itr, approved_module_ptrs_.end());

    std::for_each(
      manager_ptrs_.begin(), manager_ptrs_.end(), [](const auto & m) { m->updateObserver(); });
  }

  if (approved_module_ptrs_.empty()) {
    return SlotOutput{
      results.at("root"), is_candidate_plan_applied, is_this_failed, is_this_waiting_approval};
  }

  // use the last module's output as approved modules planning result.
  const auto approved_modules_output = [&results, this]() {
    const auto itr = std::find_if(
      approved_module_ptrs_.rbegin(), approved_module_ptrs_.rend(),
      [&results](const auto & m) { return results.count(m->name()) != 0; });

    if (itr != approved_module_ptrs_.rend()) {
      return results.at((*itr)->name());
    }
    return results.at("root");
  }();

  // if lane change module has succeeded, update current route lanelet.
  if (std::any_of(approved_module_ptrs_.begin(), approved_module_ptrs_.end(), [](const auto & m) {
        return m->getCurrentStatus() == ModuleStatus::SUCCESS &&
               m->isCurrentRouteLaneletToBeReset();
      }))
    resetCurrentRouteLanelet(data);

  // remove success module immediately.
  for (auto success_itr = std::find_if(
         approved_module_ptrs_.begin(), approved_module_ptrs_.end(),
         [](const auto & m) { return m->getCurrentStatus() == ModuleStatus::SUCCESS; });
       success_itr != approved_module_ptrs_.end();
       /* success_itr++ */) {
    if ((*success_itr)->getCurrentStatus() == ModuleStatus::SUCCESS) {
      debug_info_.scene_status.emplace_back(
        *success_itr, SceneModuleUpdateInfo::Action::DELETE, "From Approved");
      deleted_modules.push_back(*success_itr);
      deleteExpiredModules(*success_itr);
      success_itr = approved_module_ptrs_.erase(success_itr);
    } else {
      success_itr++;
    }
  }

  std::for_each(
    manager_ptrs_.begin(), manager_ptrs_.end(), [](const auto & m) { m->updateObserver(); });

  return SlotOutput{
    approved_modules_output, is_candidate_plan_applied, is_this_failed, is_this_waiting_approval};
}

BehaviorModuleOutput SubPlannerManager::run(
  const SceneModulePtr & module_ptr, const std::shared_ptr<PlannerData> & planner_data,
  const BehaviorModuleOutput & previous_module_output) const
{
  StopWatch<std::chrono::milliseconds> stop_watch;
  stop_watch.tic(module_ptr->name());

  module_ptr->setData(planner_data);
  module_ptr->setPreviousModuleOutput(previous_module_output);

  module_ptr->lockRTCCommand();
  const auto result = module_ptr->run();
  module_ptr->unlockRTCCommand();

  module_ptr->postProcess();

  module_ptr->updateCurrentState();

  module_ptr->publishObjectsOfInterestMarker();

  processing_time_.at(module_ptr->name()) += stop_watch.toc(module_ptr->name(), true);
  return result;
}

void setPreviousModuleOutput(const BehaviorModuleOutput & previous_module_output)
{
  previous_module_output_ = previous_module_output;
}

BehaviorModuleOutput SubPlannerManager::run(
  const SceneModulePtr & module_ptr, const std::shared_ptr<PlannerData> & planner_data,
  const BehaviorModuleOutput & previous_module_output) const
{
  StopWatch<std::chrono::milliseconds> stop_watch;
  stop_watch.tic(module_ptr->name());

  module_ptr->setData(planner_data);
  module_ptr->setPreviousModuleOutput(previous_module_output);

  module_ptr->lockRTCCommand();
  const auto result = module_ptr->run();
  module_ptr->unlockRTCCommand();

  module_ptr->postProcess();

  module_ptr->updateCurrentState();

  module_ptr->publishObjectsOfInterestMarker();

  processing_time_.at(module_ptr->name()) += stop_watch.toc(module_ptr->name(), true);
  return result;
}

virtual BehaviorModuleOutput run()
{
  updateData();
  const auto output = isWaitingApproval() ? planWaitingApproval() : plan();
  try {
    autoware::motion_utils::validateNonEmpty(output.path.points);
  } catch (const std::exception & ex) {
    throw std::invalid_argument("[" + name_ + "]" + ex.what());
  }
  return output;
}

bool isWaitingApproval() const
{
  return is_waiting_approval_ || current_state_ == ModuleStatus::WAITING_APPROVAL;
}

virtual BehaviorModuleOutput planWaitingApproval()
{
  path_candidate_ = std::make_shared<PathWithLaneId>(planCandidate().path_candidate);
  path_reference_ = std::make_shared<PathWithLaneId>(getPreviousModuleOutput().reference_path);

  return getPreviousModuleOutput();
}

CandidateOutput LaneChangeInterface::planCandidate() const
{
  autoware_utils::ScopedTimeTrack st(__func__, *getTimeKeeper());
  const auto selected_path = module_type_->getLaneChangePath();

  if (selected_path.path.points.empty()) {
    return {};
  }

  CandidateOutput output = assignToCandidate(selected_path, module_type_->getEgoPosition());

  updateSteeringFactorPtr(output, selected_path);
  return output;
}

BehaviorModuleOutput DynamicObstacleAvoidanceModule::plan()
{
  const auto & input_path = getPreviousModuleOutput().path;
  if (input_path.points.empty()) {
    throw std::runtime_error("input path is empty");
  }

  const auto ego_path_reserve_poly = calcEgoPathReservePoly(input_path);

  // create obstacles to avoid (= extract from the drivable area)
  std::vector<DrivableAreaInfo::Obstacle> obstacles_for_drivable_area;
  for (const auto & object : target_objects_) {
    const auto obstacle_poly = [&]() {
      if (getObjectType(object.label) == ObjectType::UNREGULATED) {
        return calcPredictedPathBasedDynamicObstaclePolygon(object, ego_path_reserve_poly);
      }

      if (parameters_->polygon_generation_method == PolygonGenerationMethod::EGO_PATH_BASE) {
        return calcEgoPathBasedDynamicObstaclePolygon(object);
      }
      if (parameters_->polygon_generation_method == PolygonGenerationMethod::OBJECT_PATH_BASE) {
        return calcObjectPathBasedDynamicObstaclePolygon(object);
      }
      throw std::logic_error("The polygon_generation_method's string is invalid.");
    }();
    if (obstacle_poly) {
      obstacles_for_drivable_area.push_back(
        {object.pose, obstacle_poly.value(), object.is_collision_left});

      appendObjectMarker(info_marker_, object.pose);
      appendExtractedPolygonMarker(debug_marker_, obstacle_poly.value(), object.pose.position.z);
    }
  }
  // generate drivable lanes
  DrivableAreaInfo current_drivable_area_info;
  if (parameters_->expand_drivable_area) {
    auto current_lanelets =
      getCurrentLanesFromPath(getPreviousModuleOutput().reference_path, planner_data_);
    std::for_each(current_lanelets.begin(), current_lanelets.end(), [&](const auto & lanelet) {
      current_drivable_area_info.drivable_lanes.push_back(
        generateExpandedDrivableLanes(lanelet, planner_data_, parameters_));
    });
  } else {
    current_drivable_area_info.drivable_lanes =
      getPreviousModuleOutput().drivable_area_info.drivable_lanes;
  }
  current_drivable_area_info.obstacles = obstacles_for_drivable_area;
  current_drivable_area_info.enable_expanding_hatched_road_markings =
    parameters_->use_hatched_road_markings;

  BehaviorModuleOutput output;
  output.path = input_path;
  output.drivable_area_info = utils::combineDrivableAreaInfo(
    current_drivable_area_info, getPreviousModuleOutput().drivable_area_info);
  output.reference_path = getPreviousModuleOutput().reference_path;
  output.turn_signal_info = getPreviousModuleOutput().turn_signal_info;
  output.modified_goal = getPreviousModuleOutput().modified_goal;

  return output;
}

bool isWaitingApproval() const
{
  return is_waiting_approval_ || current_state_ == ModuleStatus::WAITING_APPROVAL;
}

void clearCandidateModules()
{
  std::for_each(candidate_module_ptrs_.begin(), candidate_module_ptrs_.end(), [this](auto & m) {
    deleteExpiredModules(m);
  });
  candidate_module_ptrs_.clear();
}

void deleteExpiredModules(SceneModulePtr & module_ptr) const
{
  module_ptr->onExit();
  module_ptr->publishObjectsOfInterestMarker();
  module_ptr.reset();
}

void onExit()
{
  RCLCPP_DEBUG(getLogger(), "%s %s", name_.c_str(), __func__);

  if (getCurrentStatus() == ModuleStatus::SUCCESS) {
    updateRTCStatusForSuccess();
  }

  clearWaitingApproval();
  unlockNewModuleLaunch();
  unlockOutputPath();

  processOnExit();
}

void updateRTCStatusForSuccess()
{
  for (const auto & [module_name, ptr] : rtc_interface_ptr_map_) {
    if (ptr) {
      if (ptr->isRegistered(uuid_map_.at(module_name))) {
        ptr->updateCooperateStatus(
          uuid_map_.at(module_name), true, State::SUCCEEDED,
          std::numeric_limits<double>::lowest(), std::numeric_limits<double>::lowest(),
          clock_->now());
      }
    }
  }
}

void RTCInterface::updateCooperateStatus(
  const UUID & uuid, const bool safe, const uint8_t state, const double start_distance,
  const double finish_distance, const rclcpp::Time & stamp, const bool requested,
  const std::optional<bool> & override_rtc_auto_mode)
{
  std::lock_guard<std::mutex> lock(mutex_);
  // Find registered status which has same uuid
  auto itr = std::find_if(
    registered_status_.statuses.begin(), registered_status_.statuses.end(),
    [uuid](const auto & s) { return s.uuid == uuid; });

  // If there is no registered status, add it
  if (itr == registered_status_.statuses.end()) {
    CooperateStatus status;
    status.stamp = stamp;
    status.uuid = uuid;
    status.module = module_;
    status.safe = safe;
    status.requested = requested;
    status.command_status.type = Command::DEACTIVATE;
    status.state.type = State::WAITING_FOR_EXECUTION;
    status.start_distance = start_distance;
    status.finish_distance = finish_distance;
    status.auto_mode = override_rtc_auto_mode.value_or(is_auto_mode_enabled_);
    registered_status_.statuses.push_back(status);

    if (state != State::WAITING_FOR_EXECUTION)
      RCLCPP_WARN_STREAM(
        getLogger(), "[updateCooperateStatus]  Cannot register "
                       << state_to_string(state) << " as initial state" << std::endl);

    return;
  }

  auto update_status = [&](auto & status) {
    status.stamp = stamp;
    status.safe = safe;
    status.requested = requested;
    status.state.type = state;
    status.start_distance = start_distance;
    status.finish_distance = finish_distance;
  };

  // If the registered status is found, update status by considering the state transition
  if (
    itr->state.type == State::WAITING_FOR_EXECUTION &&
    (state == State::WAITING_FOR_EXECUTION || state == State::RUNNING || state == State::FAILED)) {
    update_status(*itr);
    return;
  }

  if (itr->state.type == State::RUNNING && state != State::WAITING_FOR_EXECUTION) {
    update_status(*itr);
    return;
  }

  if (itr->state.type == State::ABORTING && (state == State::ABORTING || state == State::FAILED)) {
    update_status(*itr);
    return;
  }

  if (itr->state.type == state) {
    update_status(*itr);
    return;
  }

  RCLCPP_WARN_STREAM(
    getLogger(), "[updateCooperateStatus] uuid : " << uuid_to_string(uuid)
                                                   << " cannot transit from "
                                                   << state_to_string(itr->state.type) << " to "
                                                   << state_to_string(state) << std::endl);
}

void reset()
{
  approved_module_ptrs_.clear();
  candidate_module_ptrs_.clear();
}

void resetCurrentRouteLanelet(const std::shared_ptr<PlannerData> & data)
{
  lanelet::ConstLanelet ret{};
  data->route_handler->getClosestLaneletWithinRoute(data->self_odometry->pose.pose, &ret);
  RCLCPP_DEBUG(logger_, "update current route lanelet. id:%ld", ret.id());
  *current_route_lanelet_ = ret;
}

bool RouteHandler::getClosestLaneletWithinRoute(
  const Pose & search_pose, lanelet::ConstLanelet * closest_lanelet) const
{
  if (route_lanelets_.empty() || closest_lanelet == nullptr) {
    return false;
  }
  const auto search_point = lanelet::BasicPoint2d(search_pose.position.x, search_pose.position.y);
  const auto query_nearest = boost::geometry::index::nearest(search_point, route_lanelets_.size());
  auto min_dist_to_route_lanelet = std::numeric_limits<double>::max();
  size_t nearest_id = 0;
  // search starting from the nearest bounding box
  for (auto query_it = route_lanelets_rtree_.qbegin(query_nearest);
       query_it != route_lanelets_rtree_.qend(); ++query_it) {
    const auto dist_to_bbox = boost::geometry::comparable_distance(search_point, query_it->first);
    // stop when the distance to the bounding box is larger than the min distance found so far
    if (dist_to_bbox > min_dist_to_route_lanelet) {
      break;
    }
    const auto dist = boost::geometry::comparable_distance(
      search_point, route_lanelets_[query_it->second].polygon2d().basicPolygon());
    if (dist < min_dist_to_route_lanelet) {
      min_dist_to_route_lanelet = dist;
      nearest_id = query_it->second;
    }
  }
  *closest_lanelet = route_lanelets_[nearest_id];
  return true;
}

